begin;
do $$declare st uuid;other uuid;pa uuid;ad uuid;mg uuid;exam uuid;tid uuid;eid uuid;mid uuid;sv timestamptz;nv timestamptz;pv timestamptz;rv timestamptz;rid uuid;r record;data jsonb;today date:=(now() at time zone 'Asia/Seoul')::date;
begin
select id into st from public.cheongla_profiles where role='student' and approval_status='approved' limit 1;
select id into other from public.cheongla_profiles where role='student' and approval_status='approved' and id<>st limit 1;
select id into pa from public.cheongla_profiles where role='parent' and approval_status='approved' limit 1;
select id into ad from public.cheongla_profiles where is_app_admin and approval_status='approved' limit 1;
select id into mg from public.cheongla_profiles where role='manager' and approval_status='approved' limit 1;
if st is null or other is null or pa is null or ad is null or mg is null then raise exception '검증용 승인 계정 없음';end if;
perform set_config('test.student',st::text,true);perform set_config('test.parent',pa::text,true);perform set_config('test.other',other::text,true);perform set_config('test.admin',ad::text,true);
insert into public.cheongla_parent_students(parent_id,student_id,created_by) values(pa,st,ad) on conflict do nothing;
insert into public.cheongla_tuition_notices(student_id,student_name,billing_month,period_start,period_end,monthly_fee,billable_days,month_days,amount,due_on,status,daily_fee) values(st,'검증용 학생','2098-10-01','2098-10-01','2098-10-31',450000,30,31,450000,today-1,'published',15000) returning id into tid;
insert into public.cheongla_exams(title,exam_on,deadline,status) values('검증용 시험','2098-10-16','2098-10-01 12:00+09','open') returning id into exam;
insert into public.cheongla_exam_applications(exam_id,student_id,student_name,status) values(exam,st,'검증용 학생','registered');
insert into public.cheongla_exam_fee_notices(exam_id,student_id,student_name,exam_title,exam_on,amount,due_on,status) values(exam,st,'검증용 학생','검증용 시험','2098-10-16',20000,today-1,'published') returning id into eid;
insert into public.cheongla_meal_forms(month,deadline,unit_price)values('2098-10-01',today,7500);
insert into public.cheongla_meal_submissions(month,student_id,student_name,lunch,dinner)values('2098-10-01',st,'검증용 학생',array['2098-10-01'::date,'2098-10-02'::date],array['2098-10-01'::date])returning updated_at into sv;
perform set_config('request.jwt.claim.sub',ad::text,true);
mid:=public.cheongla_save_meal_bill_v2('2098-10-01',st,today-1,-7500,'전월 차감 검증',sv,null);
select updated_at into nv from public.cheongla_meal_bills where id=mid;
perform set_config('request.jwt.claim.sub',pa::text,true);data:=public.cheongla_billing_list('2098-10-01');if exists(select 1 from jsonb_array_elements(data->'items') x where x->>'id'=mid::text) then raise exception 'FAIL meal draft exposed';end if;
perform set_config('request.jwt.claim.sub',ad::text,true);perform public.cheongla_publish_meal_bill(mid,'publish',nv);
perform public.cheongla_save_billing_config('검증 은행','000-000-000','검증 예금주','검증용 계좌, 실제 청구 아님',(select updated_at from cheongla_private.billing_settings where singleton));
perform set_config('request.jwt.claim.sub',pa::text,true);data:=public.cheongla_billing_list('2098-10-01');if jsonb_array_length(data->'items')<>3 then raise exception 'FAIL linked parent list';end if;
perform set_config('request.jwt.claim.sub',other::text,true);data:=public.cheongla_billing_list('2098-10-01');if exists(select 1 from jsonb_array_elements(data->'items') x where x->>'student_id'=st::text) then raise exception 'FAIL other student billing exposed';end if;
for r in select fee_kind,id,amount,updated_at from cheongla_private.collection_notices where id in(tid,eid,mid) loop
 nv:=r.updated_at;pv:=null;
 perform set_config('request.jwt.claim.sub',other::text,true);
 begin perform public.cheongla_report_fee_deposit(r.fee_kind,r.id,'검증용 학생',today,r.amount,'',nv);raise exception 'FAIL unrelated report';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',pa::text,true);
 begin perform public.cheongla_report_fee_deposit(r.fee_kind,r.id,'검증용 학생',today+1,r.amount,'',nv);raise exception 'FAIL future date';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 begin perform public.cheongla_report_fee_deposit(r.fee_kind,r.id,'검증용 학생',today,r.amount-1,'',nv);raise exception 'FAIL wrong amount';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 rid:=public.cheongla_report_fee_deposit(r.fee_kind,r.id,'다른 입금자명',today,r.amount,'실제 이름 대조 검증',nv);
 if not exists(select 1 from public.cheongla_notifications q where q.event_key='fee_report:'||rid::text and q.title like '%검증용 학생%' and q.title like '%입금자: 다른 입금자명%' and q.title like '%'||today::text||'%') then raise exception 'FAIL detailed deposit notification';end if;
 if exists(select 1 from public.cheongla_profiles p where p.approval_status='approved' and p.membership_state='active' and (p.is_app_admin or p.role in ('owner','english_director','math_director','manager')) and not exists(select 1 from public.cheongla_notifications q where q.recipient_id=p.id and q.event_key='fee_report:'||rid::text)) then raise exception 'FAIL staff deposit notification missing';end if;

 select updated_at into rv from cheongla_private.fee_deposit_reports where id=rid;
 if exists(select 1 from cheongla_private.fee_payments where notice_kind=r.fee_kind and notice_id=r.id and paid_at is not null) then raise exception 'FAIL report auto paid';end if;
 begin perform public.cheongla_report_fee_deposit(r.fee_kind,r.id,'검증용 학생',today,r.amount,'중복',nv);raise exception 'FAIL duplicate report';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 begin perform public.cheongla_set_fee_payment(r.fee_kind,r.id,true,nv,null);raise exception 'FAIL parent confirm';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',mg::text,true);
 begin perform public.cheongla_collection_sms_recipients(r.fee_kind,r.id,nv,true);raise exception 'FAIL pending reminder';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 perform public.cheongla_review_fee_deposit(rid,'reject','통장 입금 미확인 검증',rv,nv,null);
 perform set_config('request.jwt.claim.sub',pa::text,true);rid:=public.cheongla_report_fee_deposit(r.fee_kind,r.id,'검증용 학생',today,r.amount,'',nv);select updated_at into rv from cheongla_private.fee_deposit_reports where id=rid;
 perform public.cheongla_cancel_fee_deposit(rid,rv);
 rid:=public.cheongla_report_fee_deposit(r.fee_kind,r.id,'검증용 학생',today,r.amount,'',nv);select updated_at into rv from cheongla_private.fee_deposit_reports where id=rid;
 perform set_config('request.jwt.claim.sub',mg::text,true);perform public.cheongla_review_fee_deposit(rid,'confirm','',rv,nv,null);
 if not exists(select 1 from cheongla_private.fee_payments where notice_kind=r.fee_kind and notice_id=r.id and paid_amount=r.amount and paid_at is not null) then raise exception 'FAIL paid amount';end if;
 if (select state from cheongla_private.fee_deposit_reports where id=rid)<>'confirmed' then raise exception 'FAIL report confirm';end if;
 begin perform public.cheongla_collection_sms_recipients(r.fee_kind,r.id,nv,true);raise exception 'FAIL paid reminder';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 begin perform public.cheongla_set_fee_payment(r.fee_kind,r.id,false,nv,null);raise exception 'FAIL stale payment overwrite';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
 select updated_at into pv from cheongla_private.fee_payments where notice_kind=r.fee_kind and notice_id=r.id;
 perform public.cheongla_set_fee_payment(r.fee_kind,r.id,false,nv,pv);
 perform public.cheongla_collection_sms_recipients(r.fee_kind,r.id,nv,true);
 data:=public.cheongla_fee_collection_history(r.fee_kind,r.id);if jsonb_array_length(data->'reports')<>3 or jsonb_array_length(data->'payments')<>2 then raise exception 'FAIL collection history';end if;
end loop;
-- A changed notice must not be confirmed from an old report.
perform set_config('request.jwt.claim.sub',pa::text,true);select updated_at into nv from public.cheongla_tuition_notices where id=tid;
rid:=public.cheongla_report_fee_deposit('tuition',tid,'검증용 학생',today,450000,'',nv);select updated_at into rv from cheongla_private.fee_deposit_reports where id=rid;
update public.cheongla_tuition_notices set amount=440000,updated_at=clock_timestamp() where id=tid returning updated_at into nv;
perform set_config('request.jwt.claim.sub',mg::text,true);select updated_at into pv from cheongla_private.fee_payments where notice_kind='tuition' and notice_id=tid;
begin perform public.cheongla_review_fee_deposit(rid,'confirm','',rv,nv,pv);raise exception 'FAIL old report new amount';exception when raise_exception then if SQLERRM like 'FAIL%' then raise;end if;end;
-- Meal edits return to draft, preserving the payment history.
perform set_config('request.jwt.claim.sub',ad::text,true);select updated_at into nv from public.cheongla_meal_bills where id=mid;perform public.cheongla_save_meal_bill_v2('2098-10-01',st,today,0,'변경 검증',sv,nv);
if (select status from public.cheongla_meal_bills where id=mid)<>'draft' then raise exception 'FAIL meal edit publication';end if;
end;$$;
set local role authenticated;
do $$declare data jsonb;begin
perform set_config('request.jwt.claim.sub',current_setting('test.student'),true);data:=public.cheongla_billing_list('2098-10-01');if jsonb_array_length(data->'items')<>2 then raise exception 'FAIL own student list';end if;
begin perform 1 from cheongla_private.fee_deposit_reports;raise exception 'FAIL raw report access';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',current_setting('test.other'),true);data:=public.cheongla_billing_list('2098-10-01');if jsonb_array_length(data->'items')<>0 then raise exception 'FAIL unrelated list';end if;
perform set_config('request.jwt.claim.sub','',true);begin perform public.cheongla_billing_list('2098-10-01');raise exception 'FAIL guest list';exception when insufficient_privilege then null;end;
end;$$;
reset role;
rollback;
select 'PASS: 학원비·모의고사비·도시락비 통합 청구, 학생/연결 학부모 조회, 초안·게시, 입금 알림/중복/금액/날짜 검증, 학원 확인/반려/복원, 대기·완료 미납문자 차단, 다른 학생·비회원 차단, 처리 이력. 전부 롤백, 실제 송금·문자 발송 없음.' as result;
